create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),github_id bigint unique not null,login text not null,name text,avatar_url text not null,created_at timestamptz not null default now(),last_login_at timestamptz not null default now());
create table if not exists github_accounts(user_id uuid primary key references users on delete cascade,access_token_encrypted text not null,token_type text,scopes text,expires_at timestamptz,refresh_token_encrypted text,updated_at timestamptz not null default now());
create table if not exists repositories(id uuid primary key default gen_random_uuid(),user_id uuid not null references users on delete cascade,github_repo_id bigint not null,full_name text not null,owner text not null,name text not null,private boolean not null,default_branch text not null,description text,language text,pushed_at timestamptz,selected_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(user_id,github_repo_id));
create table if not exists sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references users on delete cascade,token_hash text unique not null,created_at timestamptz not null default now(),expires_at timestamptz not null,user_agent text,revoked_at timestamptz);
alter table sessions add column if not exists last_refreshed_at timestamptz not null default now();
create table if not exists rate_limits(key text primary key,window_start timestamptz not null,count integer not null);
alter table users enable row level security;alter table github_accounts enable row level security;alter table repositories enable row level security;alter table sessions enable row level security;alter table rate_limits enable row level security;
drop policy if exists users_own on users;create policy users_own on users using(id=current_setting('app.user_id',true)::uuid) with check(id=current_setting('app.user_id',true)::uuid);
drop policy if exists accounts_own on github_accounts;create policy accounts_own on github_accounts using(user_id=current_setting('app.user_id',true)::uuid) with check(user_id=current_setting('app.user_id',true)::uuid);
drop policy if exists repositories_own on repositories;create policy repositories_own on repositories using(user_id=current_setting('app.user_id',true)::uuid) with check(user_id=current_setting('app.user_id',true)::uuid);
drop policy if exists sessions_own on sessions;create policy sessions_own on sessions using(user_id=current_setting('app.user_id',true)::uuid) with check(user_id=current_setting('app.user_id',true)::uuid);
